import { resolveDeployEnvironment } from "../server/deploy-environment.js";
import { getRequestContext } from "../server/request-context.js";
import { legacyLifecycleEvent, withCanonicalTrackingProperties, } from "../shared/analytics-events.js";
import { ANALYTICS_CLIENT_PLATFORM_PROPERTY } from "../shared/analytics-platform.js";
import { isQaTestEmail } from "../shared/qa-test-email.js";
export { isQaTestEmail } from "../shared/qa-test-email.js";
const REGISTRY_KEY = Symbol.for("@agent-native/core/tracking.registry");
function isTrackingSuppressed(userId, properties) {
    const requestContext = getRequestContext();
    return (requestContext?.isSyntheticTraffic === true ||
        isQaTestEmail(requestContext?.userEmail) ||
        isQaTestEmail(userId) ||
        isQaTestEmail(properties?.email) ||
        isQaTestEmail(properties?.userEmail) ||
        isQaTestEmail(properties?.user_email));
}
function getRegistry() {
    const g = globalThis;
    if (!g[REGISTRY_KEY])
        g[REGISTRY_KEY] = new Map();
    return g[REGISTRY_KEY];
}
export function registerTrackingProvider(provider) {
    if (!provider?.name) {
        throw new Error("registerTrackingProvider: provider.name is required");
    }
    if (typeof provider.track !== "function") {
        throw new Error("registerTrackingProvider: provider.track must be a function");
    }
    getRegistry().set(provider.name, provider);
}
export function unregisterTrackingProvider(name) {
    return getRegistry().delete(name);
}
export function listTrackingProviders() {
    return Array.from(getRegistry().keys());
}
// `caller` is required on ActionRunContext and absent from TrackingMeta, so it
// is the one field that tells the two apart without the caller declaring which
// shape it passed.
function isActionRunContext(source) {
    return typeof source.caller === "string";
}
function resolveTrackingSource(source) {
    // The browser session rides the request, not the caller's arguments, so it
    // resolves the same way whether the UI called the action or the agent did.
    const ambientSessionId = getRequestContext()?.browserSessionId;
    if (!source)
        return { sessionId: ambientSessionId };
    if (isActionRunContext(source)) {
        return { userId: source.userEmail, sessionId: ambientSessionId };
    }
    return {
        userId: source.userId,
        anonymousId: source.anonymousId,
        sessionId: source.sessionId ?? ambientSessionId,
        occurredAt: source.occurredAt,
    };
}
export function track(name, properties, source) {
    const { userId, anonymousId, sessionId, occurredAt } = resolveTrackingSource(source);
    if (isTrackingSuppressed(userId, properties))
        return;
    const clientPlatform = getRequestContext()?.clientPlatform;
    const actionContext = source && isActionRunContext(source) ? source : undefined;
    const trackedProperties = withCanonicalTrackingProperties({
        ...(properties ?? {}),
        ...(sessionId ? { session_id: sessionId } : {}),
        ...(userId ? { user_id: userId } : {}),
        ...(actionContext?.userEmail
            ? { user_email: actionContext.userEmail }
            : {}),
        ...(actionContext?.orgId ? { workspace_id: actionContext.orgId } : {}),
        deployment_environment: resolveDeployEnvironment(),
        ...(clientPlatform
            ? { [ANALYTICS_CLIENT_PLATFORM_PROPERTY]: clientPlatform }
            : {}),
    });
    emitTrackingEvent(name, trackedProperties, {
        userId,
        anonymousId,
        sessionId,
        occurredAt,
    });
    const lifecycle = legacyLifecycleEvent(name, trackedProperties);
    if (lifecycle) {
        emitTrackingEvent(lifecycle.name, lifecycle.properties, {
            userId,
            anonymousId,
            sessionId,
            occurredAt,
        });
    }
}
function emitTrackingEvent(name, properties, source) {
    const event = {
        name,
        properties,
        // A caller-supplied `occurredAt` of 0 is not a real event time, so `||`
        // rather than `??` is deliberate here.
        timestamp: new Date(source.occurredAt || Date.now()).toISOString(),
        userId: source.userId,
        anonymousId: source.anonymousId,
        sessionId: source.sessionId,
    };
    for (const provider of getRegistry().values()) {
        try {
            const result = provider.track(event);
            if (result && typeof result.catch === "function") {
                result.catch((err) => {
                    console.error(`[tracking] Provider "${provider.name}" rejected:`, err);
                });
            }
        }
        catch (err) {
            console.error(`[tracking] Provider "${provider.name}" threw:`, err);
        }
    }
}
export function identify(userId, traits) {
    if (isTrackingSuppressed(userId, traits))
        return;
    for (const provider of getRegistry().values()) {
        if (!provider.identify)
            continue;
        try {
            const result = provider.identify(userId, traits);
            if (result && typeof result.catch === "function") {
                result.catch(() => { });
            }
        }
        catch {
            // best-effort
        }
    }
}
export function flushTracking() {
    const promises = [];
    for (const provider of getRegistry().values()) {
        if (!provider.flush)
            continue;
        try {
            const result = provider.flush();
            if (result) {
                promises.push(result.catch((err) => {
                    console.error(`[tracking] Provider "${provider.name}" flush rejected:`, err);
                }));
            }
        }
        catch (err) {
            console.error(`[tracking] Provider "${provider.name}" flush threw:`, err);
            // best-effort
        }
    }
    return Promise.all(promises);
}
